coding.referenceSolution:
function buildTree(comments) {
  const nodes = new Map(comments.map((c) => [c.id, { id: c.id, text: c.text, children: [] }]));
  const roots = [];
  for (const c of comments) {
    const parent = c.parentId === null ? undefined : nodes.get(c.parentId);
    if (parent) parent.children.push(nodes.get(c.id));
    else roots.push(nodes.get(c.id));
  }
  return roots;
}

