coding.referenceSolution:
function applyPending(server, pending) {
  let list = server;
  for (const op of pending) {
    if (op.type === "add") list = [...list, op.item];
    else if (op.type === "remove") list = list.filter((i) => i.id !== op.id);
    else if (op.type === "rename") list = list.map((i) => (i.id === op.id ? { ...i, name: op.name } : i));
  }
  return list;
}

